package com.example.starter.survey.domain;

/**
 * 船舶检验类型：年度检验、中间检验、特别检验。
 */
public enum SurveyType {
    /** 年度检验：窗口为周年日前后各 3 个月，可展期一次、最长 3 个月。 */
    ANNUAL,
    /** 中间检验：不得展期。 */
    INTERMEDIATE,
    /** 特别检验：不得展期。 */
    SPECIAL
}

package com.example.starter.survey.domain;

/**
 * 检验流转状态：申请受理 -> 登轮完成 -> 已发证（终态）。
 */
public enum SurveyStatus {
    /** 已受理申请，检验进行中。 */
    APPLIED,
    /** 已完成登轮检验，缺陷已登记。 */
    BOARDED,
    /** 已签发/换发证书，终态。 */
    CERTIFIED
}

package com.example.starter.survey.domain;

/**
 * 缺陷严重程度：重大缺陷未整改不得发证；一般缺陷限期 30 日复查。
 */
public enum DefectSeverity {
    /** 重大缺陷：发证前必须整改完成。 */
    MAJOR,
    /** 一般缺陷：限发现日起 30 日内复查，恰第 30 日受理。 */
    MINOR
}

package com.example.starter.survey.domain;

/**
 * 缺陷整改状态。
 */
public enum DefectStatus {
    /** 待整改/待复查。 */
    OPEN,
    /** 已在期限内整改并受理。 */
    RECTIFIED,
    /** 逾期提交，复查不予受理。 */
    REJECTED_LATE
}

package com.example.starter.survey.domain;

/**
 * 证书状态。同一船舶同一检验类型同一时刻至多一张 VALID 证书。
 */
public enum CertificateStatus {
    /** 有效。 */
    VALID,
    /** 已被新证替代（与新证发证在同一事务内置为失效）。 */
    SUPERSEDED,
    /** 一般缺陷逾期未合格复查，证书失效。 */
    EXPIRED
}

