package com.example.starter.survey.domain;

import java.time.LocalDate;

/**
 * 船舶（合成数据）。
 *
 * @param id                 主键
 * @param imo                IMO 编号，唯一
 * @param name               船名
 * @param annualAnniversary  年度检验周年基准日（UTC 日期，窗口按每年该日复算）
 * @param deliveryDate       交付/换证基准日（UTC 日期，用于中间、特别检验周期复算）
 */
public record Ship(
        Long id,
        String imo,
        String name,
        LocalDate annualAnniversary,
        LocalDate deliveryDate
) {
}

package com.example.starter.survey.domain;

import java.time.Instant;
import java.time.LocalDate;

/**
 * 一次检验记录（计划→申请→登轮→发证流转主体）。
 *
 * @param id                 主键
 * @param requestId          申请幂等键
 * @param shipId             船舶主键
 * @param type               检验类型
 * @param status             流转状态
 * @param cycleAnchor        本次周期锚点日（年度为当年周年日；UTC）
 * @param windowStart        申请时快照的窗口首日（含，UTC）
 * @param windowEnd          申请时快照的窗口末日（含，UTC；批准展期后另记 extensionUntil）
 * @param extensionUntil     展期后窗口/有效期末日（含，UTC），未展期为 null
 * @param appliedAt          受理时刻（UTC）
 * @param boardedAt          登轮检验完成时刻（UTC），未完成为 null
 * @param certifiedAt        发证时刻（UTC），未发证为 null
 * @param fingerprint        业务指纹（requestId + 全部业务字段）
 */
public record Survey(
        Long id,
        String requestId,
        Long shipId,
        SurveyType type,
        SurveyStatus status,
        LocalDate cycleAnchor,
        LocalDate windowStart,
        LocalDate windowEnd,
        LocalDate extensionUntil,
        Instant appliedAt,
        Instant boardedAt,
        Instant certifiedAt,
        String fingerprint
) {

    /** 是否仍处于进行中（未到发证终态）。 */
    public boolean inProgress() {
        return status != SurveyStatus.CERTIFIED;
    }
}

package com.example.starter.survey.domain;

import java.time.Instant;

/**
 * 幂等记录：requestId 为键，指纹覆盖 requestId 与全部业务字段。
 *
 * @param id           主键
 * @param requestId    幂等键，唯一
 * @param fingerprint  首次请求的业务指纹
 * @param httpStatus   首次响应 HTTP 状态码
 * @param responseBody 首次响应体 JSON（同键同参原样重放）
 * @param createdAt    首次受理时刻（UTC）
 */
public record IdempotentRecord(
        Long id,
        String requestId,
        String fingerprint,
        int httpStatus,
        String responseBody,
        Instant createdAt
) {
}

package com.example.starter.survey.domain;

import java.time.Instant;

/**
 * 检验过程事件（如签发后迟到的检验记录仅登记为迟到事件，不改变终态）。
 *
 * @param id         主键
 * @param surveyId   关联检验
 * @param eventType  事件类型，如 LATE_BOARD_RECORD
 * @param payload    事件内容 JSON
 * @param occurredAt 事件发生时刻（UTC）
 */
public record SurveyEvent(
        Long id,
        Long surveyId,
        String eventType,
        String payload,
        Instant occurredAt
) {
}

