            rs.getString("note"),
            rs.getString("fingerprint")
    );

    /** 按主键查找。 */
    public Optional<ExtensionRequest> findById(long id) {
        return jdbc.query("SELECT * FROM extension_request WHERE id = ?", MAPPER, id)
                .stream().findFirst();
    }

