        return switch (survey.type()) {
            case ANNUAL, INTERMEDIATE ->
                    survey.cycleAnchor().plusYears(1).plusMonths(3);
            case SPECIAL ->
                    survey.cycleAnchor().plusYears(5).plusMonths(3);
        };
    }
}

