            }
            return results;
        } finally {
            pool.shutdownNow();
        }
    }

    @Test
    void parallelApplicationsForSameShipAndTypeOnlyOneAccepted() throws Exception {
        registerShip("ship-pa", "IMO-PA");
        setClockDate(LocalDate.of(2026, 6, 15));

