                && !r.body.get("replayed").asBoolean()).count();
        long replay = results.stream().filter(r -> r.status == 200
                && r.body.get("replayed").asBoolean()).count();
        long inFlight = results.stream()
                .filter(r -> r.status == 409
                        && "IDEMPOTENCY_IN_FLIGHT".equals(r.body.get("code").asText()))
                .count();
